sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cfms-home {
  max-width: 1100px;
  margin: 30px auto;
  padding: 20px;
  font-family: Arial, sans-serif;
}

.hero {
  text-align: center;
  padding: 40px 20px;
  background: #337ab7;
  color: white;
  border-radius: 12px;
  margin-bottom: 30px;
}

.hero-icon {
  font-size: 45px;
}

.hero h1 {
  margin: 10px 0;
  font-size: 32px;
}

.hero p {
  font-size: 18px;
  margin: 8px;
}

.hero span {
  font-size: 14px;
}

.features {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 20px;
}

.feature-card {
  display: block;
  text-decoration: none;
  color: #222;
  background: white;
  padding: 25px;
  border-radius: 10px;
  text-align: center;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.feature-card:hover {
  transform: translateY(-4px);
}

.icon {
  font-size: 35px;
}

.feature-card h3 {
  color: #337ab7;
  margin: 12px 0 8px;
}

.feature-card p {
  font-size: 14px;
}
